// NodeMutation represents an operation that mutates the Node nodes in the graph.
type NodeMutation struct {
	node.Mutation
	config
	id       *uuid.UUID
	done     bool
	oldValue func(context.Context) (*Node, error)
}

var _ ent.Mutation = (*NodeMutation)(nil)

// nodeOption allows management of the mutation configuration using functional options.
type nodeOption func(*NodeMutation)

// newNodeMutation creates new mutation for the Node entity.
func newNodeMutation(c config, op Op, opts ...nodeOption) *NodeMutation {
	m := &NodeMutation{
		Mutation: *node.NewMutation(op),
		config:   c,
	}
	for _, opt := range opts {
		opt(m)
	}
	return m
}

// SetId sets the value of the id field. Note that this
// operation is only accepted on creation of Node entities.
func (m *NodeMutation) SetId(id uuid.UUID) {
	m.id = &id
}

// Id returns the Id value in the mutation. Note that the Id is only available
// if it was provided to the builder or after it was returned from the database.
func (m *NodeMutation) Id() (id uuid.UUID, exists bool) {
	if m.id == nil {
		return
	}
	return *m.id, true
}

// withNodeId sets the Id field of the mutation.
func withNodeId(id uuid.UUID) nodeOption {
	return func(m *NodeMutation) {
		var (
			err   error
			once  sync.Once
			value *Node
		)
		m.oldValue = func(ctx context.Context) (*Node, error) {
			once.Do(func() {
				if m.done {
					err = errors.New("querying old values post mutation is not allowed")
				} else {
					value, err = m.Client().Node.Get(ctx, id)
				}
			})
			return value, err
		}
		m.id = &id
	}
}

// withNode sets the old Node of the mutation.
func withNode(node *Node) nodeOption {
	return func(m *NodeMutation) {
		m.oldValue = func(context.Context) (*Node, error) {
			return node, nil
		}
		m.id = &node.Id
	}
}

// Client returns a new `ent.Client` from the mutation. If the mutation was
// executed in a transaction (ent.Tx), a transactional client is returned.
func (m NodeMutation) Client() *Client {
	client := &Client{config: m.config}
	client.init()
	return client
}

// Tx returns an `ent.Tx` for mutations that were executed in transactions;
// it returns an error otherwise.
func (m NodeMutation) Tx() (*Tx, error) {
	if _, ok := m.driver.(*txDriver); !ok {
		return nil, errors.New("ent: mutation is not running in a transaction")
	}
	tx := &Tx{config: m.config}
	tx.init()
	return tx, nil
}

// Ids queries the database and returns the entity ids that match the mutation's predicate.
// That means, if the mutation is applied within a transaction with an isolation level such
// as sql.LevelSerializable, the returned ids match the ids of the rows that will be updated
// or updated by the mutation.
func (m *NodeMutation) Ids(ctx context.Context) ([]uuid.UUID, error) {
	switch {
	case m.Op().Is(OpUpdateOne | OpDeleteOne):
		id, exists := m.Id()
		if exists {
			return []uuid.UUID{id}, nil
		}
		fallthrough
	case m.Op().Is(OpUpdate | OpDelete):
		return m.Client().Node.Query().Where(m.Predicates()...).Ids(ctx)
	default:
		return nil, fmt.Errorf("Ids is not allowed on %s operations", m.Op())
	}
}

